import{_ as t,c as r,o as s,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const n=JSON.parse('{"title":"数据库 Schema 与迁移","description":"","frontmatter":{"title":"数据库 Schema 与迁移","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#9.1","branch":"main","level":1,"order":9.1,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/09-infrastructure-and-deployment/01-database-schema-and-migrations.md","filePath":"posts/projects/zfeed/09-infrastructure-and-deployment/01-database-schema-and-migrations.md","lastUpdated":1779632679000}'),l={name:"posts/projects/zfeed/09-infrastructure-and-deployment/01-database-schema-and-migrations.md"};function a(c,e,i,d,q,b){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="数据库-schema-与迁移" tabindex="-1">数据库 Schema 与迁移 <a class="header-anchor" href="#数据库-schema-与迁移" aria-label="Permalink to &quot;数据库 Schema 与迁移&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/bootstrap/init.sql" target="_blank" rel="noreferrer">scripts/sql/bootstrap/init.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_article.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_article.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_comment.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_comment.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_content.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_content.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_count_value.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_count_value.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_favorite.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_favorite.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_follow.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_follow.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_like.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_like.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_like_event_outbox.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_like_event_outbox.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_mq_consume_dedup.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_mq_consume_dedup.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_user.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_user.sql</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_video.sql" target="_blank" rel="noreferrer">scripts/sql/zfeed_video.sql</a></li></ul></details><p>本页为 zfeed 微服务使用的 MySQL 数据库 schema 提供完整技术参考。系统使用名为 <code>zfeed</code> 的单一逻辑数据库来存储所有持久化领域数据，包括用户、内容、社交互动和计数；任务调度则使用独立的 <code>xxl_job</code> 数据库 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/bootstrap/init.sql#L1-L10" target="_blank" rel="noreferrer">scripts/sql/bootstrap/init.sql#1-10</a></p><h2 id="数据库初始化与-bootstrap" tabindex="-1">数据库初始化与 Bootstrap <a class="header-anchor" href="#数据库初始化与-bootstrap" aria-label="Permalink to &quot;数据库初始化与 Bootstrap&quot;">​</a></h2><p>数据库环境通过 bootstrap 脚本初始化，该脚本会创建所需数据库、用户和权限 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/bootstrap/init.sql#L1-L8" target="_blank" rel="noreferrer">scripts/sql/bootstrap/init.sql#1-8</a>。随后它执行一系列 SQL 文件来创建表并应用迁移 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/bootstrap/init.sql#L12-L25" target="_blank" rel="noreferrer">scripts/sql/bootstrap/init.sql#12-25</a></p><h3 id="sql-schema-总览" tabindex="-1">SQL Schema 总览 <a class="header-anchor" href="#sql-schema-总览" aria-label="Permalink to &quot;SQL Schema 总览&quot;">​</a></h3><p>下图将逻辑实体映射到 <code>zfeed</code> 数据库中的对应物理表。</p><p>实体到表映射</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/bootstrap/init.sql#L12-L25" target="_blank" rel="noreferrer">scripts/sql/bootstrap/init.sql#12-25</a></p><h2 id="核心领域-schema" tabindex="-1">核心领域 Schema <a class="header-anchor" href="#核心领域-schema" aria-label="Permalink to &quot;核心领域 Schema&quot;">​</a></h2><h3 id="用户管理-zfeed-user" tabindex="-1">用户管理（<code>zfeed_user</code>） <a class="header-anchor" href="#用户管理-zfeed-user" aria-label="Permalink to &quot;用户管理（`zfeed_user`）&quot;">​</a></h3><p><code>zfeed_user</code> 表存储用户资料信息和认证凭据。它使用生成列（<code>active_mobile</code>、<code>active_email</code>）只对未删除用户施加唯一约束，使手机号可以在账号删除后被再次使用 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_user.sql#L1-L28" target="_blank" rel="noreferrer">scripts/sql/zfeed_user.sql#1-28</a></p><ul><li>关键索引：</li><li><code>uk_active_mobile</code>：对活跃手机号施加唯一约束 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_user.sql#L22-L22" target="_blank" rel="noreferrer">scripts/sql/zfeed_user.sql#22</a></li><li><code>ft_user_search</code>：在 <code>nickname</code>、<code>bio</code> 和 <code>mobile</code> 上建立全文索引，供 search-rpc 使用 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_user.sql#L27-L27" target="_blank" rel="noreferrer">scripts/sql/zfeed_user.sql#27</a></li></ul><h3 id="内容层级" tabindex="-1">内容层级 <a class="header-anchor" href="#内容层级" aria-label="Permalink to &quot;内容层级&quot;">​</a></h3><p>zfeed 使用“基础表 + 扩展表”模式。<code>zfeed_content</code> 保存通用元数据，而类型专属数据位于 <code>zfeed_article</code> 或 <code>zfeed_video</code> 中 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_content.sql#L1-L17" target="_blank" rel="noreferrer">scripts/sql/zfeed_content.sql#1-17</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_article.sql#L1-L14" target="_blank" rel="noreferrer">scripts/sql/zfeed_article.sql#1-14</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_video.sql#L1-L16" target="_blank" rel="noreferrer">scripts/sql/zfeed_video.sql#1-16</a></p><table tabindex="0"><thead><tr><th>表</th><th>主要用途</th><th>关键字段</th></tr></thead><tbody><tr><td><code>zfeed_content</code></td><td>元数据与排序</td><td><code>hot_score</code>, <code>visibility</code>, <code>published_at</code></td></tr><tr><td><code>zfeed_article</code></td><td>长文本内容</td><td><code>title</code>, <code>content</code>（LONGTEXT）, <code>cover</code></td></tr><tr><td><code>zfeed_video</code></td><td>视频媒体</td><td><code>origin_url</code>, <code>duration</code>, <code>transcode_status</code></td></tr></tbody></table><ul><li>排序支持：<code>zfeed_content</code> 包含 <code>idx_hot_score</code>（<code>hot_score</code>、<code>id</code>），用于支持推荐引擎高效检索热门内容 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_content.sql#L23-L23" target="_blank" rel="noreferrer">scripts/sql/zfeed_content.sql#23</a></li></ul><h3 id="互动与社交图谱" tabindex="-1">互动与社交图谱 <a class="header-anchor" href="#互动与社交图谱" aria-label="Permalink to &quot;互动与社交图谱&quot;">​</a></h3><p>社交互动通过状态表追踪，这些表支持软删除和用于幂等性的版本控制。</p><ul><li><code>zfeed_like</code> 与 <code>zfeed_favorite</code>：使用 <code>scene</code> 和 <code>content_id</code> 区分对文章、视频或评论的点赞/收藏 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_like.sql#L1-L19" target="_blank" rel="noreferrer">scripts/sql/zfeed_like.sql#1-19</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_favorite.sql#L1-L19" target="_blank" rel="noreferrer">scripts/sql/zfeed_favorite.sql#1-19</a></li><li><code>zfeed_comment</code>：使用 <code>parent_id</code>（直接父评论）和 <code>root_id</code>（顶层评论）实现线程式评论结构 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_comment.sql#L1-L27" target="_blank" rel="noreferrer">scripts/sql/zfeed_comment.sql#1-27</a></li><li><code>zfeed_follow</code>：追踪 follower/followee 关系，并对关系对设置唯一约束 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_follow.sql#L1-L16" target="_blank" rel="noreferrer">scripts/sql/zfeed_follow.sql#1-16</a></li></ul><h2 id="可靠消息与计数器" tabindex="-1">可靠消息与计数器 <a class="header-anchor" href="#可靠消息与计数器" aria-label="Permalink to &quot;可靠消息与计数器&quot;">​</a></h2><h3 id="transactional-outbox" tabindex="-1">Transactional Outbox <a class="header-anchor" href="#transactional-outbox" aria-label="Permalink to &quot;Transactional Outbox&quot;">​</a></h3><p>为了保证互动事件投递到 Kafka 时具备 “Exactly-Once” 或 “At-Least-Once” 语义，系统使用 outbox 表。</p><ul><li><code>zfeed_like_event_outbox</code>：在与状态变更相同的数据库事务中保存点赞事件。随后由 <code>LikeOutboxRelay</code> 轮询该表 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_like_event_outbox.sql#L1-L16" target="_blank" rel="noreferrer">scripts/sql/zfeed_like_event_outbox.sql#1-16</a></li></ul><h3 id="计数系统-zfeed-count-value" tabindex="-1">计数系统（<code>zfeed_count_value</code>） <a class="header-anchor" href="#计数系统-zfeed-count-value" aria-label="Permalink to &quot;计数系统（`zfeed_count_value`）&quot;">​</a></h3><p><code>count-rpc</code> 服务在该表中管理所有高频计数。它使用 <code>biz_type</code> 和 <code>target_type</code> 判别字段，以统一格式存储点赞数、收藏数、评论数和关注数 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_count_value.sql#L1-L15" target="_blank" rel="noreferrer">scripts/sql/zfeed_count_value.sql#1-15</a></p><ul><li>乐观锁：<code>version</code> 列用于避免并发递增时发生丢失更新 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_count_value.sql#L7-L7" target="_blank" rel="noreferrer">scripts/sql/zfeed_count_value.sql#7</a></li></ul><h3 id="mq-幂等-zfeed-mq-consume-dedup" tabindex="-1">MQ 幂等（<code>zfeed_mq_consume_dedup</code>） <a class="header-anchor" href="#mq-幂等-zfeed-mq-consume-dedup" aria-label="Permalink to &quot;MQ 幂等（`zfeed_mq_consume_dedup`）&quot;">​</a></h3><p><code>count-rpc</code> consumer 使用该表确保经由 Canal 处理的 MySQL binlog 事件不会被重复应用 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_mq_consume_dedup.sql#L1-L10" target="_blank" rel="noreferrer">scripts/sql/zfeed_mq_consume_dedup.sql#1-10</a></p><h2 id="迁移策略" tabindex="-1">迁移策略 <a class="header-anchor" href="#迁移策略" aria-label="Permalink to &quot;迁移策略&quot;">​</a></h2><p>代码库采用幂等迁移模式。它没有使用传统的顺序迁移文件，例如 <code>v1__init.sql</code>、<code>v2__add_col.sql</code>，而是在每个 SQL 文件中使用 <code>IF NOT EXISTS</code> 子句，并通过 MySQL <code>PREPARE/EXECUTE</code> 语句执行动态 DDL 块 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_article.sql#L16-L31" target="_blank" rel="noreferrer">scripts/sql/zfeed_article.sql#16-31</a></p><p>迁移逻辑流程</p><h3 id="示例-动态添加索引" tabindex="-1">示例：动态添加索引 <a class="header-anchor" href="#示例-动态添加索引" aria-label="Permalink to &quot;示例：动态添加索引&quot;">​</a></h3><p>在 <code>zfeed_comment.sql</code> 中，脚本会先检查 <code>information_schema.statistics</code>，再尝试添加 <code>idx_content_root_status_list</code> 索引，以避免重复执行时报错 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_comment.sql#L29-L42" target="_blank" rel="noreferrer">scripts/sql/zfeed_comment.sql#29-42</a></p><h3 id="示例-生成列迁移" tabindex="-1">示例：生成列迁移 <a class="header-anchor" href="#示例-生成列迁移" aria-label="Permalink to &quot;示例：生成列迁移&quot;">​</a></h3><p>在 <code>zfeed_user.sql</code> 中，迁移逻辑会在缺失时动态添加 <code>active_mobile</code> 生成列，确保现有部署可以平滑升级 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_user.sql#L30-L45" target="_blank" rel="noreferrer">scripts/sql/zfeed_user.sql#30-45</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_article.sql#L16-L31" target="_blank" rel="noreferrer">scripts/sql/zfeed_article.sql#16-31</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_comment.sql#L29-L42" target="_blank" rel="noreferrer">scripts/sql/zfeed_comment.sql#29-42</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_user.sql#L30-L45" target="_blank" rel="noreferrer">scripts/sql/zfeed_user.sql#30-45</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/sql/zfeed_favorite.sql#L21-L34" target="_blank" rel="noreferrer">scripts/sql/zfeed_favorite.sql#21-34</a></p>',37)])])}const h=t(l,[["render",a]]);export{n as __pageData,h as default};
